import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-cell-biology-signaling-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`How do steroid and peptide hormones signal differently?`]: {
    question: r`Two hormones are each chemically attached to large beads that cannot enter cells, then added to cultured target cells. Which bead-bound hormone can still trigger its normal response, and why?`,
    options: [r`Cortisol, since its receptor sits on the cell surface`, r`Glucagon, since its receptor sits inside the cytosol`, r`Glucagon, since its receptor sits on the cell surface`, r`Cortisol, since its receptor sits inside the cytosol`],
    correctAnswer: 2,
    explanation: r`Glucagon is a peptide hormone that binds a surface receptor, so it works without entering the cell. Cortisol is a steroid whose receptor is intracellular, so a cortisol molecule held outside the cell cannot reach it. The two options that swap the receptor locations reverse the steroid and peptide patterns.`,
  },
  [r`What is signal amplification?`]: {
    question: r`In a model cell, one hormone-bound receptor activates 10 G proteins. Each G protein switches on one adenylyl cyclase, and each cyclase makes 100 cAMP before it shuts off. How many cAMP molecules result from one bound hormone molecule?`,
    options: [r`About 1,000 cAMP molecules`, r`About 110 cAMP molecules`, r`About 100 cAMP molecules`, r`About 10 cAMP molecules`],
    correctAnswer: 0,
    explanation: r`Each tier multiplies the one before it: 10 G proteins × 100 cAMP each gives 1,000 cAMP from one hormone. Adding the tiers (10 + 100) gives 110, which treats amplification as additive. Answers of 100 or 10 count only one tier and ignore the other.`,
  },
  [r`Contrast autocrine, paracrine, and endocrine signaling.`]: {
    question: r`An activated T cell secretes interleukin-2. The interleukin-2 binds receptors on the very T cell that released it and drives that cell to divide. How is this signal classified?`,
    options: [r`Endocrine, because the signal is carried to its target by blood`, r`Paracrine, because the signal acts on a neighbouring cell type`, r`Synaptic, because the signal crosses a narrow cleft to its target`, r`Autocrine, because the signal acts on the cell that secreted it`],
    correctAnswer: 3,
    explanation: r`A signal that acts back on the cell that released it is autocrine. Paracrine signals act on nearby cells other than the sender, and endocrine signals travel in the blood to distant targets. Nothing in the description involves a synaptic cleft or a second cell at all.`,
  },
  [r`How is a signaling cascade terminated?`]: {
    question: r`Cells are loaded with a GTP analog that cannot be hydrolyzed, then given a brief pulse of a Gs-coupled hormone. cAMP stays high long after the hormone is washed away. Which off-switch has the analog defeated?`,
    options: [r`Breakdown of cAMP to AMP by phosphodiesterase`, r`Inactivation of G-alpha by its own GTPase activity`, r`Removal of phosphates from targets by phosphatases`, r`Release of the hormone from its surface receptor`],
    correctAnswer: 1,
    explanation: r`G-alpha turns itself off by hydrolyzing its bound GTP to GDP, so an analog that cannot be hydrolyzed leaves G-alpha, and therefore the cyclase, permanently on. Phosphodiesterase and phosphatases still work in these cells, but they cannot keep up with a cyclase that never stops. The hormone was washed away, so receptor occupancy is not the problem.`,
  },
  [r`What is apoptosis and how does it differ from necrosis?`]: {
    question: r`In a tissue section, scattered cells are shrunken with condensed chromatin and blebbing but intact membranes. Their DNA is cut into regular fragments, and no immune cells have gathered around them. What is occurring?`,
    options: [r`Apoptosis, which is run by caspases and causes no inflammation`, r`Necrosis, which is run by caspases and causes no inflammation`, r`Apoptosis, which is run by cell swelling and causes inflammation`, r`Necrosis, which is run by cell swelling and causes inflammation`],
    correctAnswer: 0,
    explanation: r`Shrinkage, intact membranes, orderly DNA cutting and the absence of inflammation mark programmed, caspase-driven apoptosis. Necrosis is uncontrolled injury: the cell swells, bursts and spills its contents, which draws immune cells. The mixed options attach the caspase mechanism to necrosis or the swelling and inflammation to apoptosis.`,
  },
  [r`Describe the G-protein coupled receptor cascade.`]: {
    question: r`A cell carries one receptor coupled to $G_s$ and a second receptor coupled to $G_i$. Compared with stimulating the $G_s$ receptor alone, stimulating both receptors together makes the cell's cAMP level:`,
    options: [r`Higher, because $G_i$ also activates adenylate cyclase`, r`Unchanged, because $G_i$ acts only on phospholipase C`, r`Lower, because $G_i$ inhibits adenylate cyclase`, r`Higher, because $G_i$ blocks the phosphodiesterase`],
    correctAnswer: 2,
    explanation: r`$G_s$ stimulates adenylate cyclase and $G_i$ inhibits the same enzyme, so the two inputs oppose each other and cAMP ends up lower than with $G_s$ alone. Saying $G_i$ activates the cyclase confuses it with $G_s$, and saying it acts on phospholipase C confuses it with $G_q$. $G_i$ has no action on phosphodiesterase.`,
  },
  [r`Name the common second messengers.`]: {
    question: r`Vasopressin binds a receptor on smooth muscle. The receptor activates $G_q$, which activates phospholipase C (PLC). $IP_{3}$ and DAG appear, cytosolic $Ca^{2+}$ rises, and protein kinase C (PKC) phosphorylates its targets. Which list contains only second messengers?`,
    options: [r`$G_q$, $IP_{3}$ and DAG`, r`$IP_{3}$, DAG and $Ca^{2+}$`, r`PLC, DAG and PKC`, r`Vasopressin and $IP_{3}$`],
    correctAnswer: 1,
    explanation: r`Second messengers are the small molecules or ions produced or released inside the cell after the receptor is activated: here $IP_{3}$, DAG and $Ca^{2+}$. Vasopressin is the first messenger. $G_q$ is a transducer protein, and PLC and PKC are enzymes that make or respond to the messengers.`,
  },
  [r`What do receptor tyrosine kinases do?`]: {
    question: r`A mutant EGF receptor has every tyrosine in its cytoplasmic tail replaced by phenylalanine. Its kinase domain is intact, and it binds EGF and pairs up normally. What is the result when EGF is added?`,
    options: [r`Pairs cannot form, so the kinase domain is never switched on`, r`Signaling is normal, since Ras docks on the kinase domain itself`, r`Signaling is constant, since tail tyrosines normally inhibit it`, r`Pairs form, but SH2 adaptors find no phosphotyrosine docking sites`],
    correctAnswer: 3,
    explanation: r`The phosphorylated tail tyrosines are the docking sites that SH2-domain adaptors use to launch the Ras/MAPK and PI3K/Akt cascades, so without them the signal stops at the receptor. Pairing is stated to be normal. Ras does not dock on the kinase domain, and the tail tyrosines are activating platforms, not brakes.`,
  },
  [r`Which membrane is impermeable to most ions, creating the proton gradient?`]: {
    question: r`A compound is added to isolated mitochondria that lets H⁺ leak freely across the inner mitochondrial membrane. The electron transport chain itself is undamaged. What happens?`,
    options: [r`Electron transport continues, but ATP synthesis falls sharply`, r`Electron transport stops, but ATP synthesis carries on as before`, r`Electron transport and ATP synthesis both stop at the same time`, r`Nothing changes, as the outer membrane still holds the gradient`],
    correctAnswer: 0,
    explanation: r`ATP synthase is driven by the proton gradient, which exists only because the inner membrane is impermeable to ions. A leak collapses the gradient, so ATP synthesis falls while the chain keeps passing electrons to oxygen. The outer membrane has porins and is freely permeable, so it cannot hold a proton gradient.`,
  },
  [r`Homologous chromosomes differ from sister chromatids in that homologs:`]: {
    question: r`A person is heterozygous (Aa) at one gene. In one of their cells in G2, with no crossing over, which pair of DNA molecules carries different alleles at this gene, and why?`,
    options: [r`The two sister chromatids, which came from different parents`, r`The two sister chromatids, which were copied during S phase`, r`The two homologous chromosomes, which came from different parents`, r`The two homologous chromosomes, which were copied during S phase`],
    correctAnswer: 2,
    explanation: r`Homologs are inherited one from each parent, so in a heterozygote one carries A and the other carries a. Sister chromatids are the identical products of replicating one chromosome in S phase, so both carry the same allele. The mixed options give the origin of one pair to the other.`,
  },
  [r`Alternative splicing allows one gene to:`]: {
    question: r`One gene, read from one promoter, gives a membrane-bound protein in young B cells and a shorter secreted protein in mature ones. The DNA is identical in both, but the two mature mRNAs contain different exons. What produces the two proteins?`,
    options: [r`Cleavage of one finished polypeptide by a protease`, r`Transcription of two separate copies of the gene`, r`Mutation of the gene in the mature B cells only`, r`Alternative splicing of the same primary transcript`],
    correctAnswer: 3,
    explanation: r`Different exon combinations in mRNAs made from one unchanged gene are the signature of alternative splicing, which lets one gene encode several protein isoforms. Protease cleavage would act after translation and would not change the exons in the mRNA. The DNA is stated to be identical, which rules out a mutation or a second gene copy.`,
  },
  [r`Order the secretory pathway correctly:`]: {
    question: r`A pancreatic cell is making a digestive enzyme for secretion. A drug is added that blocks all transport out of the endoplasmic reticulum. Where does newly made enzyme pile up?`,
    options: [r`In the Golgi, the compartment that feeds the rough ER`, r`In the rough ER, the compartment that feeds the Golgi`, r`In secretory vesicles, the carriers that feed the Golgi`, r`At the plasma membrane, the site that feeds the vesicles`],
    correctAnswer: 1,
    explanation: r`Secreted proteins travel from the rough ER to the Golgi, then into vesicles, then to the plasma membrane. Blocking exit from the ER traps the enzyme at the first station, the rough ER. The other options place the Golgi, vesicles or membrane earlier in the route than they really are.`,
  },
  [r`Prokaryotes lack:`]: {
    question: r`In E. coli, ribosomes begin translating an mRNA while RNA polymerase is still transcribing it. In a human cell, a nuclear gene's mRNA is never translated during its transcription. What feature of the bacterium allows the coupling?`,
    options: [r`It has no ribosomes free in its cytoplasm`, r`It has no plasma membrane around the cell`, r`It has no nuclear membrane around its DNA`, r`It has no RNA polymerase of its own`],
    correctAnswer: 2,
    explanation: r`Bacterial DNA lies in the nucleoid with no membrane around it, so ribosomes can reach an mRNA as it is being made. In eukaryotes the nuclear envelope separates transcription from the ribosomes in the cytoplasm. Bacteria do have ribosomes, a plasma membrane and their own RNA polymerase.`,
  },
  [r`Which antibiotic targets the bacterial 30S ribosomal subunit?`]: {
    question: r`A bacterial strain becomes resistant through a change in its small ribosomal subunit; the large subunit is unaltered. Tetracycline and the macrolide erythromycin are tested. Which drug has most likely lost its binding site?`,
    options: [r`Tetracycline, because it binds the 30S subunit`, r`Erythromycin, because it binds the 30S subunit`, r`Tetracycline, because it binds the 50S subunit`, r`Erythromycin, because it binds the 50S subunit`],
    correctAnswer: 0,
    explanation: r`The small bacterial subunit is 30S, and tetracycline is the drug that binds it, so a change there removes tetracycline's site. Macrolides such as erythromycin bind the large 50S subunit, which is unaltered here. The mixed options attach each drug to the other drug's subunit.`,
  },
  [r`Gap junctions permit:`]: {
    question: r`A small fluorescent dye (about 400 Da) injected into one heart muscle cell spreads within seconds into its neighbours without entering the fluid outside the cells. A 50 kDa fluorescent protein injected the same way stays put. Which structure explains both results?`,
    options: [r`Tight junctions, which seal neighbouring cells to each other`, r`Desmosomes, which pass small proteins from cell to cell`, r`Gap junctions, which pass molecules of any size between cells`, r`Gap junctions, which pass only ions and small molecules`],
    correctAnswer: 3,
    explanation: r`Gap junctions are channels that join the cytoplasm of adjacent cells and admit ions and small molecules but not proteins, which fits a dye that spreads and a protein that does not. Tight junctions seal the space between cells and desmosomes anchor cells mechanically; neither connects cytoplasm. A pore open to any size would have let the protein through.`,
  },
  [r`The Grb2-bound protein {{c1::SOS}} is the GEF that loads {{c2::GTP}} onto membrane-anchored Ras.`]: {
    question: r`In a test tube, purified Ras holding GDP is mixed with free GTP, and almost no Ras-GTP forms. When the catalytic part of SOS is added, Ras-GTP forms quickly. What does SOS do to Ras?`,
    options: [r`It adds a phosphate to the GDP bound to Ras, making GTP`, r`It releases the GDP from Ras so that free GTP can bind`, r`It hydrolyzes the GTP on Ras, which switches Ras on`, r`It adds a lipid to Ras so that it can reach the GTP`],
    correctAnswer: 1,
    explanation: r`SOS is a guanine nucleotide exchange factor: it pries GDP off Ras, and GTP from solution then fills the empty site. It does not phosphorylate the bound GDP, which is the usual misreading of "exchange". Hydrolyzing GTP is the job of a GAP and turns Ras off, and SOS does not attach lipids.`,
  },
  [r`How does the thyroid hormone receptor differ from the classic cytosolic steroid receptor model?`]: {
    question: r`With no thyroid hormone present, a gene controlled by the thyroid hormone receptor is transcribed less in normal cells than in cells that lack the receptor entirely. What explains this?`,
    options: [r`The empty receptor waits in the cytosol bound to HSP90`, r`The empty receptor sits on the DNA and recruits corepressors`, r`The empty receptor sits on the DNA and recruits coactivators`, r`The empty receptor is destroyed before it reaches the DNA`],
    correctAnswer: 1,
    explanation: r`The thyroid hormone receptor stays in the nucleus on its response element even without hormone and actively represses the gene through corepressors, so removing the receptor relieves that repression. Waiting in the cytosol with HSP90 describes the glucocorticoid receptor. Coactivators are recruited only after T3 binds, and a destroyed receptor could not repress anything.`,
  },
  [r`Trace nitric oxide signaling from endothelium to smooth muscle relaxation.`]: {
    question: r`The endothelium is stripped from a ring of artery, leaving only smooth muscle. Acetylcholine, which normally relaxes the intact ring by acting on the endothelium, now has no relaxing effect. Which agent would still relax the ring, and why?`,
    options: [r`Nitroglycerin, because it supplies NO to the muscle directly`, r`More acetylcholine, because it supplies NO to the muscle directly`, r`Arginine, because smooth muscle converts it straight into cGMP`, r`Added Ca²⁺, because it activates the muscle's guanylyl cyclase`],
    correctAnswer: 0,
    explanation: r`NO is normally made by the endothelial enzyme eNOS and diffuses into the muscle, where it activates soluble guanylyl cyclase and raises cGMP. Nitroglycerin donates NO itself, so it works without endothelium. Acetylcholine only triggers the endothelium, arginine is the substrate for the missing eNOS and is not turned into cGMP, and Ca²⁺ in smooth muscle causes contraction.`,
  },
  [r`cGMP is hydrolyzed by phosphodiesterases; the ANP receptor is a membrane-bound {{c1::receptor guanylyl cyclase}} that makes cGMP with no G protein.`]: {
    question: r`A shortened ANP receptor is missing its whole cytoplasmic portion but still spans the membrane and binds ANP normally. Cells that have only this receptor are given ANP. What happens to cGMP?`,
    options: [r`It rises normally, since a G protein relays the signal`, r`It rises normally, since NO activates the soluble cyclase`, r`It does not rise, since the lost portion was the cyclase`, r`It does not rise, since the lost portion held the G protein`],
    correctAnswer: 2,
    explanation: r`The ANP receptor is itself a guanylyl cyclase: its cytoplasmic portion makes cGMP when ANP binds outside, so removing that portion removes the enzyme. No G protein takes part in this pathway, so neither option built on a G protein applies. NO activates a different, soluble cyclase and is not produced by ANP binding.`,
  },
  [r`Insulin receptor signaling is terminated in part by {{c1::PTP1B}} removing the receptor's activating phosphotyrosines.`]: {
    question: r`Mice are engineered to lack PTP1B. Compared with normal mice given the same dose of insulin, how do their muscle and liver cells respond?`,
    options: [r`More weakly, since the receptor's phosphotyrosines persist`, r`More weakly, since the receptor is never phosphorylated`, r`More strongly, since the receptor's phosphoserines persist`, r`More strongly, since the receptor's phosphotyrosines persist`],
    correctAnswer: 3,
    explanation: r`PTP1B is a protein tyrosine phosphatase that removes the activating phosphotyrosines from the insulin receptor, so without it the receptor stays active longer and the response is stronger. A weaker response gets the direction backward. The activating marks on this receptor are on tyrosine, not serine, and PTP1B removes phosphates instead of adding them.`,
  },
  [r`Which receptor family signals through SMAD proteins, and how?`]: {
    question: r`A drug blocks the kinase activity of the TGF-beta type I receptor. Ligand still binds and the type II receptor is unaffected. Which event is the first to be lost?`,
    options: [r`Serine/threonine phosphorylation of the receptor SMADs`, r`Tyrosine phosphorylation of the receptor SMAD proteins`, r`Serine/threonine phosphorylation of the type I receptor`, r`Tyrosine phosphorylation of STAT proteins by JAK kinases`],
    correctAnswer: 0,
    explanation: r`TGF-beta receptors are serine/threonine kinases: type II phosphorylates type I, and type I then phosphorylates the receptor SMADs, so blocking type I first removes SMAD phosphorylation. Phosphorylation of the type I receptor is done by the unaffected type II receptor and still occurs. Tyrosine phosphorylation and JAK-STAT belong to other receptor families.`,
  },
  [r`Why is Ca2+ signaling spatially confined, and how do cells exploit these microdomains?`]: {
    question: r`Ca²⁺ channels in a nerve terminal open briefly. Vesicles docked a few nanometres from the channels fuse, but identical vesicles one micrometre away, with the same Ca²⁺ sensor, do not. Why does the signal fail to reach them?`,
    options: [r`Ca²⁺ is too large an ion to move through the cytosol at all`, r`Ca²⁺ ions attract each other and stay clustered at the pore`, r`Ca²⁺ is converted to cAMP before it can reach those vesicles`, r`Ca²⁺ is bound by buffers and pumped away before it spreads far`],
    correctAnswer: 3,
    explanation: r`Cytosolic buffer proteins and pumps capture free Ca²⁺ within a very short distance of an open channel, so the concentration is high only in a small zone around the pore. That is why cells place sensors such as synaptotagmin right beside the channels. Ca²⁺ is a small ion, like charges repel, and an ion cannot be converted into cAMP.`,
  },
  [r`Ligand-gated ion channels respond within {{c1::milliseconds}} — the nicotinic ACh receptor opens its cation pore after binding {{c2::two}} ACh molecules.`]: {
    question: r`A toxin permanently blocks one of the acetylcholine binding sites on each nicotinic receptor at a muscle end plate. Acetylcholine is then released and binds every site that is still free. What do the receptors do?`,
    options: [r`They open fully, because one bound acetylcholine is enough`, r`They stay closed, because two bound acetylcholines are needed`, r`They open slowly, because a G protein now relays the signal`, r`They stay closed, because four bound acetylcholines are needed`],
    correctAnswer: 1,
    explanation: r`The nicotinic receptor opens only when both of its two acetylcholine sites are occupied, so with one site blocked the pore stays shut. One acetylcholine is not enough, and the number needed is two, not four. This receptor is itself the ion channel and never uses a G protein, which is why it normally responds within milliseconds.`,
  },
  [r`Steroid hormone receptors are ligand-activated {{c1::transcription factors}} that bind DNA at {{c2::hormone response elements}}.`]: {
    question: r`A researcher wants a reporter gene to be switched on by cortisol in cells that already contain the glucocorticoid receptor. What must be placed in the DNA upstream of the reporter gene?`,
    options: [r`A cAMP response element, which is bound by CREB after PKA acts`, r`A signal sequence, which sends the reporter to the cell surface`, r`A hormone response element, which the receptor itself binds`, r`A phosphotyrosine motif, which the receptor's SH2 domain binds`],
    correctAnswer: 2,
    explanation: r`The cortisol-bound receptor is itself a transcription factor that attaches to a hormone response element in DNA, so adding that element makes the gene cortisol-inducible. A cAMP response element serves surface receptors that signal through PKA and CREB, which steroids do not use. A signal sequence is a protein-sorting tag, and phosphotyrosine motifs belong to receptor tyrosine kinase signaling.`,
  },
  [r`Liver epinephrine: beta receptor -> Gs -> cAMP -> PKA -> phosphorylase kinase -> glycogen {{c1::phosphorylase}}; PKA also inhibits glycogen {{c2::synthase}}.`]: {
    question: r`Liver cells with an inactive mutant phosphorylase kinase are treated with epinephrine. cAMP rises and PKA is activated normally. What is the state of the two glycogen enzymes?`,
    options: [r`Phosphorylase is activated, but synthase is not inhibited`, r`Phosphorylase is activated, and synthase is inhibited`, r`Synthase is inhibited, but phosphorylase is not activated`, r`Synthase is activated, and phosphorylase is inhibited`],
    correctAnswer: 2,
    explanation: r`PKA inhibits glycogen synthase directly, but it reaches glycogen phosphorylase only through phosphorylase kinase. With that relay dead, synthase is still shut off while phosphorylase is never switched on. The option that activates synthase and inhibits phosphorylase describes the insulin-like opposite state.`,
  },
  [r`Why do steroid hormone effects take hours while epinephrine acts within seconds?`]: {
    question: r`Liver cells are pretreated with a drug that blocks all protein synthesis, then given either cortisol or epinephrine. Which hormone's main effect is abolished, and why?`,
    options: [r`Cortisol's, because it depends on newly made protein`, r`Epinephrine's, because it depends on newly made protein`, r`Both, because each one depends on newly made protein`, r`Neither, because both only modify existing enzymes`],
    correctAnswer: 0,
    explanation: r`Cortisol acts by changing transcription, so its effect needs new mRNA to be translated into protein and is lost when translation is blocked. Epinephrine works by phosphorylating enzymes that already exist, so it still acts within seconds. This is also why steroid effects take hours and epinephrine's do not.`,
  },
  [r`How does calmodulin convert a Ca2+ spike into enzyme activity?`]: {
    question: r`A drug binds Ca²⁺-loaded calmodulin and stops it from wrapping around its target proteins. A cell treated with the drug is stimulated, and cytosolic Ca²⁺ rises as usual. What follows?`,
    options: [r`Ca²⁺ activates CaMKII and MLCK directly, so nothing is lost`, r`Ca²⁺ cannot rise after all, so CaMKII and MLCK stay inactive`, r`Ca²⁺ rises, but only PKA and adenylyl cyclase stay inactive`, r`Ca²⁺ rises, but CaMKII and MLC kinase are not activated`],
    correctAnswer: 3,
    explanation: r`These kinases do not sense Ca²⁺ themselves. Calmodulin binds the Ca²⁺, changes shape and wraps around CaMKII and myosin light-chain kinase to activate them, so blocking that contact silences them even though Ca²⁺ is high. The drug acts after Ca²⁺ has risen, and PKA is controlled by cAMP, not by calmodulin.`,
  },
  [r`Signals must switch off. Name termination mechanisms at the ligand, receptor, transducer, and second-messenger levels.`]: {
    question: r`Four cell lines each have one broken off-switch. In which one is the defect at the level of the transducer, that is, the G protein?`,
    options: [r`A line lacking arrestin, so that receptors stay coupled longer`, r`A line lacking RGS proteins, so that G-alpha holds GTP longer`, r`A line lacking phosphodiesterase, so that cAMP persists longer`, r`A line lacking acetylcholinesterase, so that ligand lasts longer`],
    correctAnswer: 1,
    explanation: r`The transducer is the G protein, which is switched off by GTP hydrolysis that RGS proteins accelerate. Arrestin acts on the receptor, phosphodiesterase removes the second messenger cAMP, and acetylcholinesterase destroys the ligand. Each of the other lines therefore fails at a different level of the pathway.`,
  },
  [r`An activated GPCR acts as a {{c1::guanine nucleotide exchange factor (GEF)}}, causing G-alpha to swap {{c2::GDP for GTP}} and separate from beta-gamma.`]: {
    question: r`A mutant G-alpha grips GDP so tightly that an activated receptor cannot dislodge it. After hormone binds the receptor, what state is this G protein in?`,
    options: [r`G-alpha keeps its GDP but separates from beta-gamma`, r`G-alpha converts its GDP to GTP and then separates`, r`G-alpha binds GTP and remains active indefinitely`, r`G-alpha keeps its GDP and stays joined to beta-gamma`],
    correctAnswer: 3,
    explanation: r`The activated receptor works as an exchange factor: it must release GDP from G-alpha so that GTP can bind, and only the GTP form separates from beta-gamma. If GDP cannot leave, the trimer stays intact and inactive. The receptor never phosphorylates GDP into GTP, and staying active indefinitely would need bound GTP that cannot be hydrolyzed.`,
  },
  [r`Contrast the effectors of G-alpha-s, G-alpha-i, and G-alpha-q.`]: {
    question: r`Acetylcholine slows pacemaker cells of the heart through a Gi-coupled receptor. The slowing still occurs when adenylyl cyclase is completely blocked beforehand, and it depends on K⁺ leaving the cell. Which component produces it?`,
    options: [r`The freed beta-gamma dimer, by opening K⁺ channels`, r`The freed G-alpha-s subunit, by opening K⁺ channels`, r`The freed G-alpha-q subunit, by releasing stored Ca²⁺`, r`The freed beta-gamma dimer, by closing K⁺ channels`],
    correctAnswer: 0,
    explanation: r`When a G protein is activated, the beta-gamma dimer signals too. In pacemaker cells it opens K⁺ channels, and the outward K⁺ current slows the heart with no change in cAMP required. Closing K⁺ channels would stop the K⁺ efflux described. G-alpha-s and G-alpha-q are not released by a Gi-coupled receptor.`,
  },
  [r`G-alpha-q activates {{c1::phospholipase C-beta}}, which cleaves PIP2 into {{c2::IP3}} and DAG.`]: {
    question: r`Cells are stimulated through a Gq-coupled receptor, then quickly broken open and separated into a membrane fraction and a soluble cytosol fraction. Where are the two products of PIP2 cleavage found?`,
    options: [r`Both IP3 and DAG in the cytosol fraction`, r`DAG in the cytosol and IP3 in the membrane`, r`IP3 in the cytosol and DAG in the membrane`, r`Both IP3 and DAG in the membrane fraction`],
    correctAnswer: 2,
    explanation: r`Phospholipase C-beta cuts the membrane lipid PIP2 into a water-soluble head group, IP3, and a lipid remnant, DAG. IP3 diffuses through the cytosol to the ER, while DAG stays embedded in the membrane. The reversed option swaps the soluble and lipid products, and the other two ignore that the products have different solubility.`,
  },
  [r`After PIP2 cleavage, how do IP3 and DAG converge to activate protein kinase C?`]: {
    question: r`Cells are loaded with a chelator that prevents any rise in cytosolic Ca²⁺. A Gq-coupled receptor is then stimulated, and DAG is produced in normal amounts. How does conventional protein kinase C respond?`,
    options: [r`Fully activated, because DAG alone is enough to switch it on`, r`Poorly activated, because it needs Ca²⁺ together with DAG`, r`Fully activated, because IP3 binds and switches it on directly`, r`Poorly activated, because DAG cannot be made without Ca²⁺`],
    correctAnswer: 1,
    explanation: r`Conventional PKC is switched on at the membrane by Ca²⁺ and DAG together. IP3's role is to release the Ca²⁺ from the ER, so with Ca²⁺ held down the DAG branch alone is not enough. IP3 does not bind PKC, and DAG was stated to be made normally, so a lack of DAG is not the reason.`,
  },
  [r`Amplification: one bound receptor activates many G proteins, each cyclase makes many {{c1::cAMP}}, and each kinase phosphorylates many substrates.`]: {
    question: r`In a mutant cell, each active adenylyl cyclase makes only 1 cAMP before it shuts off, where a normal cyclase makes about 100. Every other step of the hormone cascade is unchanged. How does the final output compare with normal?`,
    options: [r`About 100-fold lower, since the tiers multiply one another`, r`About 100 molecules lower, since the tiers add to one another`, r`Unchanged, since the kinase tier makes up for the lost cAMP`, r`Unchanged, since only the receptor tier amplifies the signal`],
    correctAnswer: 0,
    explanation: r`Total output is the product of the gain at every catalytic tier, so removing a 100-fold gain at the cyclase cuts the final output about 100-fold. Treating the tiers as additive greatly understates the loss. The kinase tier multiplies whatever cAMP signal it receives and cannot restore it, and amplification happens at every tier, not only at the receptor.`,
  },
  [r`How does a cAMP signal reach the genome?`]: {
    question: r`Liver cells carry a CREB in which serine 133 has been changed to alanine. Glucagon is added; cAMP rises and PKA is activated normally. What is observed?`,
    options: [r`CRE-driven genes turn on, but glycogen breakdown is lost`, r`Glycogen breakdown is normal, but CRE-driven genes stay off`, r`Glycogen breakdown and CRE-driven genes are both lost`, r`Both are normal, because cAMP binds CREB directly`],
    correctAnswer: 1,
    explanation: r`PKA's catalytic subunits enter the nucleus and phosphorylate CREB on Ser133, which lets CREB recruit its coactivator and switch on genes with CRE elements. Without that serine the gene response is lost, while PKA's cytosolic targets, such as the glycogen enzymes, are still phosphorylated. cAMP never binds CREB; it acts only through PKA.`,
  },
  [r`How do cholera and pertussis toxins each freeze G-protein signaling?`]: {
    question: r`Two dishes of cells are pretreated, one with cholera toxin and one with pertussis toxin. Both then receive a brief pulse of a Gs-coupled hormone that is washed away. In which dish does cAMP stay at its stimulated level long after the washout?`,
    options: [r`Pertussis, because G-alpha-s can no longer hydrolyze its GTP`, r`Pertussis, because G-alpha-i is locked in its GTP-bound state`, r`Cholera, because G-alpha-i is locked in its GTP-bound state`, r`Cholera, because G-alpha-s can no longer hydrolyze its GTP`],
    correctAnswer: 3,
    explanation: r`Cholera toxin modifies G-alpha-s so that it cannot hydrolyze GTP, which leaves it stuck on and keeps adenylyl cyclase running after the hormone is gone. Pertussis toxin acts on G-alpha-i and locks it in the inactive GDP state, so it does not hold G-alpha-s on. Neither toxin locks G-alpha-i in a GTP-bound state.`,
  },
  [r`What limits how long G-alpha stays active, and what do RGS proteins add?`]: {
    question: r`Rod cells from a mouse lacking the RGS protein that acts on the rod's G protein are given a brief flash of light. Compared with normal rods, how long does the G protein signal last, and why?`,
    options: [r`Shorter, because GTP on G-alpha is hydrolyzed more quickly`, r`Shorter, because GDP on G-alpha is released more quickly`, r`Longer, because GTP on G-alpha is hydrolyzed more slowly`, r`Longer, because GDP on G-alpha is released more slowly`],
    correctAnswer: 2,
    explanation: r`RGS proteins are GAPs that speed up G-alpha's slow intrinsic GTP hydrolysis. Without one, G-alpha holds GTP longer and the signal is prolonged. The shorter-signal options reverse the effect, and GDP release is the activation step controlled by the receptor, not the off-step controlled by RGS.`,
  },
  [r`Outline homologous desensitization of a GPCR.`]: {
    question: r`A mutant beta-adrenergic receptor has every serine and threonine in its cytoplasmic tail changed to alanine. It binds agonist and activates Gs normally. During an hour of continuous agonist, how does its signaling compare with the normal receptor?`,
    options: [r`It persists, since arrestin has no phosphorylated tail to bind`, r`It fades sooner, since arrestin binds a bare tail more tightly`, r`It persists, since the G protein can no longer hydrolyze GTP`, r`It never begins, since the tail is where the agonist binds`],
    correctAnswer: 0,
    explanation: r`Desensitization starts when GRKs phosphorylate serines and threonines on the active receptor's tail; beta-arrestin then binds, blocks G protein coupling and drives internalization. With no sites to phosphorylate, arrestin is not recruited and signaling continues. The G protein's GTPase is unaffected by a receptor mutation, and agonist binds the outer face of the receptor, not the tail.`,
  },
  [r`cAMP activates PKA by binding its {{c1::regulatory}} subunits, releasing the two {{c2::catalytic}} subunits.`]: {
    question: r`A cell line makes the catalytic subunits of protein kinase A but no regulatory subunits. What is the state of the catalytic subunits in these cells?`,
    options: [r`Inactive even with cAMP, since nothing is left to activate them`, r`Active only with cAMP, since cAMP binds the catalytic subunits`, r`Active even without cAMP, since nothing holds them in check`, r`Inactive until cAMP is added, since cyclase must bind them`],
    correctAnswer: 2,
    explanation: r`The regulatory subunits are inhibitors: they hold the catalytic subunits inactive until cAMP binds the regulatory subunits and frees them. With no regulatory subunits, the catalytic subunits are free and active whether or not cAMP is present. cAMP does not bind the catalytic subunits, and adenylyl cyclase never touches PKA.`,
  },
  [r`cAMP is degraded to AMP by {{c1::phosphodiesterases}}; methylxanthines like caffeine inhibit them, prolonging the signal.`]: {
    question: r`An inhibitor completely shuts down adenylyl cyclase in a cell, and its cAMP falls to zero. Caffeine is then added at a dose that fully acts on its usual target. What happens to cAMP?`,
    options: [r`It rises sharply, since caffeine is converted into cAMP`, r`It stays at zero, since blocking breakdown makes no cAMP`, r`It rises sharply, since caffeine activates the Gs protein`, r`It rises slowly, since caffeine turns AMP back into cAMP`],
    correctAnswer: 1,
    explanation: r`Caffeine inhibits phosphodiesterase, the enzyme that degrades cAMP to AMP. That only preserves cAMP that the cyclase has made, so with the cyclase off there is nothing to preserve and cAMP stays at zero. Caffeine is not a substrate for cAMP synthesis, does not act on Gs, and blocking a hydrolysis enzyme does not run the reaction backward.`,
  },
  [r`RTK activation: ligand induces receptor {{c1::dimerization}}, enabling trans-{{c2::autophosphorylation}} of cytoplasmic tyrosines.`]: {
    question: r`An antibody with two identical arms binds the outer part of a growth factor receptor and activates it with no growth factor present. A one-armed fragment of the same antibody binds equally well but does not activate. Why does the two-armed form work?`,
    options: [r`It fills the ligand site, so each receptor phosphorylates itself`, r`It pairs two receptors, so each one exchanges its GDP for GTP`, r`It blocks the ligand site, so the receptors are taken into the cell`, r`It pairs two receptors, so each one phosphorylates the other`],
    correctAnswer: 3,
    explanation: r`Receptor tyrosine kinases are activated by being brought together in pairs, which lets each kinase domain phosphorylate tyrosines on its partner. Two arms can hold two receptors together; one arm cannot. Simply occupying the receptor is not enough, as the one-armed fragment shows, and exchanging GDP for GTP is what G proteins do, not these receptors.`,
  },
  [r`What do SH2 domains recognize, and how does the adaptor Grb2 use them?`]: {
    question: r`A mutant Grb2 has an SH2 domain that no longer folds, while its SH3 domains are normal. Growth factor is added and the receptor's tail tyrosines are phosphorylated as usual. What can this Grb2 still do?`,
    options: [r`Dock on the receptor's tail, but not hold on to SOS`, r`Hold on to SOS, but not dock on the receptor's tail`, r`Dock and hold SOS, but not phosphorylate Ras itself`, r`Hold on to SOS and phosphorylate the receptor's tail`],
    correctAnswer: 1,
    explanation: r`Grb2's SH2 domain is what binds the phosphotyrosines on the activated receptor, and its SH3 domains are what hold SOS. Losing SH2 leaves Grb2 carrying SOS but unable to bring it to the receptor at the membrane, so Ras is not activated. Grb2 is an adaptor with no catalytic activity, so it never phosphorylates anything.`,
  },
  [r`How does the insulin receptor deviate from the standard RTK model, and what are its two major output branches?`]: {
    question: r`Cells are engineered to lack all IRS proteins. Insulin binds its receptor, and the receptor's kinase is activated normally. What happens to signaling beyond the receptor?`,
    options: [r`The PI3K/Akt and Ras/MAPK branches both fail`, r`The PI3K/Akt and Ras/MAPK branches both run`, r`Only the Ras/MAPK branch fails; PI3K/Akt runs`, r`Only the cAMP and PKA branch fails to start`],
    correctAnswer: 0,
    explanation: r`The insulin receptor passes its signal on by phosphorylating IRS scaffold proteins, and IRS feeds both the PI3K/Akt branch and the Ras/MAPK branch. Without IRS, an active receptor kinase has nothing to hand the signal to, so both branches are lost. Insulin does not signal through cAMP and PKA.`,
  },
  [r`PI3K phosphorylates PIP2 to {{c1::PIP3}}, recruiting Akt to the membrane; the tumor suppressor {{c2::PTEN}} reverses this step.`]: {
    question: r`Tumor cells have lost both copies of PTEN. Growth factor is removed from their medium, so PI3K is no longer being stimulated. What happens to Akt in these cells, and why?`,
    options: [r`It shuts off, because PIP3 can no longer be made from PIP2`, r`It shuts off, because Akt can no longer be held by PIP2`, r`It stays active, because PIP2 is not converted into PIP3`, r`It stays active, because PIP3 is not converted back to PIP2`],
    correctAnswer: 3,
    explanation: r`PTEN is the lipid phosphatase that turns PIP3 back into PIP2. Without it, PIP3 lingers in the membrane, keeps Akt docked and active, and the survival signal continues without growth factor. Making PIP3 from PIP2 is the job of PI3K, not PTEN, and Akt is recruited by PIP3, not PIP2.`,
  },
  [r`Where does the unliganded glucocorticoid receptor reside, and what does cortisol binding change?`]: {
    question: r`A glucocorticoid receptor is engineered without its nuclear localization signal. It still binds HSP90 and cortisol normally. After cortisol is added, what does this receptor do?`,
    options: [r`It keeps HSP90 bound and still moves into the nucleus`, r`It enters the nucleus but cannot bind to any DNA site`, r`It releases HSP90 but stays behind in the cytosol`, r`It moves to the cell surface and raises cAMP there`],
    correctAnswer: 2,
    explanation: r`Cortisol binding makes the receptor release HSP90, which normally uncovers the nuclear localization signal so the receptor can be imported into the nucleus. With no such signal, the freed receptor remains in the cytosol and cannot reach its response elements. HSP90 release still occurs, and steroid receptors do not work at the membrane through cAMP.`,
  },
  [r`Cytosolic free Ca2+ is held near {{c1::$10^{-7}$}} M (vs about $10^{-3}$ M outside) by SERCA, the plasma membrane Ca2+ ATPase, and {{c2::NCX}}.`]: {
    question: r`A resting cell with typical Ca²⁺ levels sits in fluid containing about $10^{-3}$ M Ca²⁺. A channel opens briefly and raises free Ca²⁺ next to it to 100 times the resting cytosolic level. What is the local concentration?`,
    options: [r`About $10^{-3}$ M, now equal to the level outside`, r`About $10^{-5}$ M, still far below the level outside`, r`About $10^{-1}$ M, now far above the level outside`, r`About $10^{-9}$ M, still far below the level outside`],
    correctAnswer: 1,
    explanation: r`Resting cytosolic Ca²⁺ is about $10^{-7}$ M, so a 100-fold rise gives $10^{-5}$ M, still 100 times below the $10^{-3}$ M outside. Answers of $10^{-3}$ M or $10^{-1}$ M start from a resting level that is far too high. $10^{-9}$ M divides by 100 when the level went up.`,
  },
  [r`Why are phosphatases as essential to signaling as kinases? Name the major Ser/Thr and Tyr examples.`]: {
    question: r`Resting cells receive no hormone but are treated with a drug that inhibits PP1 and PP2A. Over the next hour, phosphate builds up on serine and threonine residues of many proteins. What does this result show?`,
    options: [r`PP1 and PP2A normally attach these phosphates to the proteins`, r`The drug is acting as a hormone through a surface receptor`, r`Kinases act at a low rate all the time and are normally reversed`, r`Tyrosine phosphatases normally remove these same phosphates`],
    correctAnswer: 2,
    explanation: r`Phosphorylation level is a balance: kinases have some activity even at rest, and PP1 and PP2A continually strip serine and threonine phosphates to hold the baseline low. Block the phosphatases and the phosphate accumulates. Phosphatases remove phosphates and never add them, and tyrosine phosphatases such as PTP1B act on phosphotyrosine, not these residues.`,
  },
  [r`How do cytokine receptors signal despite lacking intrinsic kinase activity?`]: {
    question: r`Red blood cell precursors are engineered to lack JAK2. Erythropoietin still binds its receptor and clusters the receptor chains. Why is there no response?`,
    options: [r`No kinase is present to phosphorylate the receptor tails`, r`No ligand site is left, since JAK2 forms that site`, r`No G protein is present to carry the signal to STATs`, r`No receptor kinase domain can find its STAT substrate`],
    correctAnswer: 0,
    explanation: r`Cytokine receptors have no kinase domain of their own and rely on associated JAKs to phosphorylate the receptor tails, which creates the docking sites for STATs. Without JAK2 nothing is phosphorylated, so STATs are never recruited or activated. Ligand binding is stated to be normal, and this pathway uses no G protein.`,
  },
  [r`Name the three-tier kinase cascade downstream of Ras and its cellular endpoint.`]: {
    question: r`Cells are pretreated with a drug that inhibits MEK and are then given growth factor. Which pattern of pathway activity is found?`,
    options: [r`ERK is phosphorylated, but Raf has not been activated`, r`Neither Raf nor ERK shows any sign of activation`, r`Both Raf and ERK are activated just as in untreated cells`, r`Raf is activated, but ERK has not been phosphorylated`],
    correctAnswer: 3,
    explanation: r`The order is Ras, then Raf, then MEK, then ERK. Blocking MEK leaves everything upstream of it working, so Ras-GTP still activates Raf, but ERK, which only MEK phosphorylates, stays off. Options that leave Raf inactive or ERK active place MEK at the wrong point in the cascade.`,
  },
  [r`Why does the Ras G12V mutation cause constitutive signaling even though GEFs are unaffected?`]: {
    question: r`Purified normal Ras and Ras G12V are each loaded with GTP in a test tube, and a GTPase-activating protein (GAP) is added to both. What is seen?`,
    options: [r`Both proteins hydrolyze their GTP at the same fast rate`, r`G12V Ras hydrolyzes its GTP faster than normal Ras does`, r`Normal Ras hydrolyzes its GTP; G12V Ras keeps its GTP`, r`G12V Ras hydrolyzes its GTP; normal Ras keeps its GTP`],
    correctAnswer: 2,
    explanation: r`The G12V change removes Ras's own GTPase activity and makes it insensitive to GAP, so GTP stays bound and Ras stays on. Normal Ras responds to GAP by hydrolyzing GTP quickly and switching off. The other options either reverse the two proteins or ignore the defect.`,
  },
  [r`Expressing a kinase-dead receptor tyrosine kinase suppresses signaling by the normal receptor in the same cell. Explain the dominant negative effect.`]: {
    question: r`A receptor missing its whole kinase domain is expressed at ten times the level of the cell's normal receptor. Growth factor is supplied in large excess, yet the response is almost abolished. What does this show about how the normal receptor works?`,
    options: [r`It works alone, and each receptor phosphorylates its own tail`, r`It works in pairs, and each partner must activate the other`, r`It works alone, and the mutant uses up the growth factor`, r`It works in pairs, and only one partner needs a kinase domain`],
    correctAnswer: 1,
    explanation: r`If receptors act as pairs that phosphorylate each other, a normal receptor paired with a kinase-less partner is wasted, and an excess of the mutant ties up most normal receptors. A receptor that worked alone would be unaffected by the mutant's presence. Growth factor is in large excess, so the mutant is not starving normal receptors of ligand, and if one kinase per pair were enough the response would survive.`,
  },
  [r`One antagonist shifts a dose-response curve right without lowering the maximum; another lowers the maximum. Classify each.`]: {
    question: r`With a fixed dose of a competitive antagonist present, 10 nM agonist gives only 10% of the maximal response; without the antagonist it gave 50%. What response is expected if the agonist is raised to a very high concentration with the antagonist still present?`,
    options: [r`It stays near 10% of maximum, as the receptors are lost for good`, r`It levels off at about half of maximum, however much is added`, r`It falls toward zero, as the agonist and blocker now bind together`, r`It approaches the original maximum, as agonist displaces blocker`],
    correctAnswer: 3,
    explanation: r`A competitive antagonist shares the agonist's binding site, so enough agonist outcompetes it and the full maximum is recovered; the curve is shifted right, not lowered. A response capped at 10% or 50% describes noncompetitive or irreversible antagonism, where receptors are removed from the usable pool. More agonist never drives the response down.`,
  },
  [r`Why do steroid hormones persist in circulation for hours while epinephrine is cleared in minutes?`]: {
    question: r`A patient has an inherited deficiency of corticosteroid-binding globulin. Compared with a healthy person, how long does a given cortisol molecule survive in this patient's plasma, and why?`,
    options: [r`A shorter time, since less of it is shielded by carrier protein`, r`A longer time, since less of it is trapped by carrier protein`, r`The same time, since cortisol dissolves freely in plasma water`, r`A longer time, since free cortisol escapes the liver's enzymes`],
    correctAnswer: 0,
    explanation: r`Steroids are lipophilic and circulate mostly bound to carriers such as corticosteroid-binding globulin, which protects them from filtration and metabolism and gives them long half-lives. With less carrier, more cortisol is free and is cleared faster. Binding prolongs survival, not shortens it, and cortisol is poorly soluble in water, which is why it needs a carrier.`,
  },
  [r`In insulin resistance, inflammatory kinases phosphorylate IRS-1 on {{c1::serine}} residues, blocking the {{c2::tyrosine}} phosphorylation that recruits PI3K.`]: {
    question: r`Fat cells exposed to an inflammatory signal stop moving GLUT4 to the surface in response to insulin, although insulin binds and the receptor kinase is active. In a second cell line, the IRS-1 residue targeted by the inflammatory kinase is changed to alanine. How does this line respond to insulin under inflammation?`,
    options: [r`It fails, because the activating tyrosine can no longer be marked`, r`It fails, because insulin can no longer bind the receptor`, r`It responds, because the inhibitory serine can no longer be marked`, r`It responds, because the receptor no longer needs IRS-1`],
    correctAnswer: 2,
    explanation: r`Inflammatory kinases switch IRS-1 off by phosphorylating serine residues, which blocks the tyrosine phosphorylation that recruits PI3K. Replacing that serine with alanine removes the inhibitory site, so the insulin receptor can still phosphorylate IRS-1 on tyrosine and GLUT4 moves. The altered residue is the inhibitory serine, not the activating tyrosine, and insulin binding was never the problem.`,
  },
  [r`Adrenergic coupling: beta receptors use {{c1::Gs}}, alpha-1 uses {{c2::Gq}}, and alpha-2 uses Gi.`]: {
    question: r`One dish of cells expressing only beta-1 receptors receives the beta-1 agonist dobutamine. A second dish expressing only alpha-1 receptors receives the alpha-1 agonist methoxamine. Which second-messenger changes are measured?`,
    options: [r`Dobutamine raises IP3; methoxamine raises cAMP`, r`Dobutamine raises cAMP; methoxamine raises IP3`, r`Dobutamine raises cAMP; methoxamine lowers cAMP`, r`Dobutamine lowers cAMP; methoxamine raises IP3`],
    correctAnswer: 1,
    explanation: r`Beta receptors couple to Gs, which stimulates adenylyl cyclase and raises cAMP. Alpha-1 receptors couple to Gq, which activates phospholipase C and raises IP3 and Ca²⁺. Lowering cAMP is the Gi response of alpha-2 receptors, and the first option swaps the Gs and Gq assignments.`,
  },
  [r`A colon cancer with an activating KRAS mutation does not respond to an anti-EGFR antibody. Why?`]: {
    question: r`Tumor X overproduces a normal EGF receptor and has normal Ras. Tumor Y has a normal amount of EGF receptor and a Ras locked in its GTP-bound form. Both are treated with an antibody that blocks the EGF receptor. Which tumor's MAPK signaling is silenced?`,
    options: [r`Only X, because the lesion in Y lies downstream of the block`, r`Only Y, because the lesion in Y lies downstream of the block`, r`Both, because Ras needs the receptor in order to stay active`, r`Neither, because Ras lies upstream of the EGF receptor`],
    correctAnswer: 0,
    explanation: r`Ras acts downstream of the receptor. In tumor X the excess signal starts at the receptor, so blocking it works. In tumor Y, Ras is on regardless of the receptor, so blocking an upstream step cannot silence it. A Ras locked with GTP no longer needs the receptor, and Ras is not upstream of it.`,
  },
  [r`Why can combining a nitrate with a PDE5 inhibitor cause life-threatening hypotension?`]: {
    question: r`A nitrate with a PDE5 inhibitor is dangerous because one drug raises production of a messenger while the other blocks its removal. Which pair of drugs uses the same logic on a different messenger?`,
    options: [r`A beta agonist given with a beta receptor antagonist`, r`A nitrate given with a guanylyl cyclase inhibitor`, r`A PDE5 inhibitor given with a NO synthase inhibitor`, r`A beta agonist given with a cAMP phosphodiesterase inhibitor`],
    correctAnswer: 3,
    explanation: r`A beta agonist raises cAMP production through Gs and adenylyl cyclase, and a cAMP phosphodiesterase inhibitor blocks cAMP breakdown, which mirrors the nitrate and PDE5 inhibitor pairing for cGMP. An agonist with its antagonist, or a nitrate with a cyclase inhibitor, oppose each other. A PDE5 inhibitor with a NO synthase inhibitor blocks removal but also cuts production.`,
  },
  [r`Pseudohypoparathyroidism and McCune-Albright syndrome involve the same G protein subunit. How do their mutations differ?`]: {
    question: r`A child has low blood calcium even though parathyroid hormone (PTH) is high. When PTH is injected, the kidney makes almost no cAMP. The PTH receptor is normal. Which defect best explains this?`,
    options: [r`A gain of function in Gs-alpha, giving hormone resistance`, r`A loss of function in Gs-alpha, giving hormone resistance`, r`A gain of function in Gs-alpha, giving constant signaling`, r`A loss of function in Gi-alpha, giving hormone resistance`],
    correctAnswer: 1,
    explanation: r`PTH signals through Gs to raise cAMP, so a Gs-alpha that does not work leaves the kidney unresponsive: PTH is high but its effect is missing. That is pseudohypoparathyroidism. A gain of function in Gs-alpha causes constant signaling without hormone, as in McCune-Albright syndrome, not resistance. Losing Gi-alpha would remove inhibition and raise cAMP.`,
  },
  [r`Neurofibromin, product of the tumor suppressor {{c1::NF1}}, is a GTPase-activating protein for Ras, so losing it leaves Ras {{c2::hyperactive}}.`]: {
    question: r`Schwann cells that have lost both copies of NF1 are compared with normal Schwann cells shortly after growth factor is withdrawn. What fraction of their Ras is bound to GTP, and why?`,
    options: [r`A low fraction, because GTP on Ras is hydrolyzed too quickly`, r`A high fraction, because GDP on Ras is released too slowly`, r`A high fraction, because GTP on Ras is hydrolyzed too slowly`, r`A low fraction, because SOS can no longer load GTP onto Ras`],
    correctAnswer: 2,
    explanation: r`Neurofibromin is a GAP that speeds GTP hydrolysis on Ras. Without it Ras-GTP is turned off only by Ras's slow intrinsic activity, so more Ras stays GTP-bound and active. Faster hydrolysis is the opposite of losing a GAP. GDP release and SOS belong to the loading step run by the exchange factor, which NF1 loss does not touch.`,
  },
  [r`Nuclear MAPK phosphorylates factors such as Elk-1, inducing the immediate early genes {{c1::FOS and JUN}}, whose products form {{c2::AP-1}}.`]: {
    question: r`Cells are given growth factor together with a drug that blocks all protein synthesis. Transcription is unaffected. What happens to FOS mRNA and to the later genes that depend on AP-1?`,
    options: [r`FOS mRNA still rises, but AP-1 target genes are not induced`, r`AP-1 target genes are induced, but FOS mRNA does not rise`, r`Neither FOS mRNA nor the AP-1 target genes are induced`, r`Both rise as usual, since ERK needs no new protein to act`],
    correctAnswer: 0,
    explanation: r`FOS is an immediate early gene: it is switched on by factors such as Elk-1 that already exist and only need phosphorylating, so its mRNA rises without new protein. AP-1 is made of newly translated Fos and Jun proteins, so the second wave of genes cannot start when translation is blocked. ERK does act without new protein, but AP-1 cannot form without it.`,
  },
  [r`NF-kB is held in the cytosol by {{c1::IkB}}; once IKK phosphorylates IkB it is ubiquitinated and destroyed, freeing NF-kB to enter the nucleus.`]: {
    question: r`Cells express a mutant IkB lacking the residues that IKK phosphorylates. It binds NF-kB normally. The cells are exposed to TNF, and IKK is activated. Where is NF-kB found, and why?`,
    options: [r`In the nucleus, because the IkB is not destroyed`, r`In the nucleus, because IKK acts on NF-kB directly`, r`In the cytosol, because NF-kB is not yet synthesized`, r`In the cytosol, because the IkB is not destroyed`],
    correctAnswer: 3,
    explanation: r`IkB keeps NF-kB in the cytosol until IKK phosphorylates IkB, which marks it for ubiquitination and destruction. An IkB that cannot be phosphorylated survives and goes on holding NF-kB in the cytosol. NF-kB is already made and merely sequestered, and it is released by loss of IkB, not by IKK acting on NF-kB.`,
  },
  [r`Without Wnt, a destruction complex containing {{c1::APC}} and GSK-3 marks beta-catenin for degradation; Wnt blocks this so beta-catenin enters the nucleus.`]: {
    question: r`A colon cell has lost both copies of APC and is growing with no Wnt in its surroundings. What happens to beta-catenin in this cell?`,
    options: [r`It is degraded faster than normal, even if Wnt is added`, r`It stays at a low level until Wnt reaches the cell`, r`It accumulates and enters the nucleus with no Wnt present`, r`It is released from the cell and acts as a Wnt signal`],
    correctAnswer: 2,
    explanation: r`APC is part of the destruction complex that marks beta-catenin for degradation when Wnt is absent. Without APC the complex fails, so beta-catenin is stable, enters the nucleus and drives growth genes as if Wnt were always present. Faster degradation or a continued need for Wnt assumes the complex still works, and beta-catenin is not a secreted signal.`,
  },
  [r`Rising cytosolic Ca2+ usually acts through calmodulin, but in smooth muscle the decisive target is {{c1::myosin light chain kinase}}.`]: {
    question: r`A drug that selectively inhibits myosin light chain kinase is applied to a strip of artery smooth muscle and to a strip of skeletal muscle. Both are then stimulated so that cytosolic Ca²⁺ rises. Which strips contract?`,
    options: [r`The smooth muscle only, since its Ca²⁺ acts through troponin C`, r`The skeletal muscle only, since its Ca²⁺ acts through troponin C`, r`Neither, since Ca²⁺ acts through this kinase in all muscle`, r`Both, since Ca²⁺ binds myosin directly in all muscle`],
    correctAnswer: 1,
    explanation: r`In smooth muscle, Ca²⁺-calmodulin must activate myosin light chain kinase for contraction, so the drug blocks that strip. In skeletal muscle Ca²⁺ binds troponin C directly and the kinase is not needed, so that strip contracts. The other options give smooth muscle the troponin mechanism or assume all muscle shares one Ca²⁺ sensor.`,
  },
  [r`$K_d$ is the ligand concentration that occupies {{c1::half the receptors}}, so a lower $K_d$ means {{c2::higher affinity}}.`]: {
    question: r`A hormone occupies half of its normal receptors at 5 nM. On a mutant receptor, half occupancy is reached only at 50 nM. What is the mutant's $K_d$, and how does its affinity compare?`,
    options: [r`$K_d$ is 50 nM, a tenfold lower affinity`, r`$K_d$ is 50 nM, a tenfold higher affinity`, r`$K_d$ is 25 nM, a fivefold lower affinity`, r`$K_d$ is 100 nM, a tenfold higher affinity`],
    correctAnswer: 0,
    explanation: r`$K_d$ is the ligand concentration at which half the receptors are occupied, so the mutant's $K_d$ is 50 nM. A higher $K_d$ means more ligand is needed to fill the receptors, which is lower affinity, here tenfold lower than the normal 5 nM. Reading a larger $K_d$ as higher affinity inverts the relationship, and 25 nM or 100 nM halve or double the half-occupancy value.`,
  },
  [r`Epinephrine raises cAMP in both cardiac muscle and bronchial smooth muscle, yet one contracts harder and the other relaxes. How?`]: {
    question: r`A membrane-permeant cAMP analog that activates PKA is added to isolated heart muscle cells and to isolated airway smooth muscle cells, with no hormone present. What is expected?`,
    options: [r`The same response in both, since the same messenger was raised`, r`No response in either, since the receptor step was bypassed`, r`Opposite responses, since the analog binds different receptors`, r`Opposite responses, since PKA has different targets in each`],
    correctAnswer: 3,
    explanation: r`The response to cAMP is set by what PKA phosphorylates in each cell: Ca²⁺ channels and phospholamban in heart muscle, giving stronger contraction, and myosin light chain kinase in smooth muscle, giving relaxation. The same messenger therefore gives opposite results. The analog acts inside the cell, so no receptor is needed or involved.`,
  },
  [r`A mutant cell makes no cAMP after hormone treatment but responds normally to forskolin. Where is the defect?`]: {
    question: r`Four mutant cell lines all fail to make cAMP when given a Gs-coupled hormone. Forskolin is then added to each. Which line still fails to make cAMP?`,
    options: [r`The line lacking the hormone's receptor`, r`The line lacking the Gs alpha subunit`, r`The line lacking adenylyl cyclase itself`, r`The line lacking a beta-gamma dimer`],
    correctAnswer: 2,
    explanation: r`Forskolin activates adenylyl cyclase directly, so it bypasses any defect upstream of the cyclase. Lines missing the receptor or a G protein subunit therefore make cAMP with forskolin. Only the line with no cyclase has nothing for forskolin to act on.`,
  },
}
